import fs from 'fs';
import path from 'path';


const MARKDOWN_SHAPE_RE = /^(#|---|\*\*|[A-Za-z0-9][^\n]*\n#{1,3}\s)/;

export interface DesignSystem {
  slug: string;
  name: string;
  category: string;
  description: string;
  keywords: string[];
  externalUrl: string;
}

const designMdDir = path.resolve(__dirname, 'designmd');
const DESIGN_MD_BY_SLUG = new Map<string, string>();

const toDisplayName = (slug: string): string =>
  slug
    .replace(/[._-]+/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');

const stripFrontmatter = (markdown: string): string => {
  if (!markdown.startsWith('---\n')) {
    return markdown;
  }
  const frontmatterEnd = markdown.indexOf('\n---\n', 4);
  if (frontmatterEnd === -1) {
    return markdown;
  }
  return markdown.slice(frontmatterEnd + 5);
};

const parseDescription = (markdown: string): string => {
  const markdownBody = stripFrontmatter(markdown).trim();
  const firstParagraph = markdownBody.split(/\n\s*\n/)[0] ?? '';
  return firstParagraph.replace(/\s+/g, ' ').trim().slice(0, 220);
};

const buildKeywords = (slug: string): string[] => {
  const slugWords = slug
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
  return Array.from(new Set([slug.toLowerCase(), ...slugWords]));
};

const loadDesignSystems = (): DesignSystem[] => {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(designMdDir, { withFileTypes: true });
  } catch {
    return [];
  }
  if (!Array.isArray(entries)) return [];
  return entries
    .filter((entry) => entry.isFile() && entry.name.endsWith('.md'))
    .map((entry) => entry.name)
    .sort((first, second) => first.localeCompare(second))
    .map((filename) => {
      const slug = filename.slice(0, -3);
      const markdownPath = path.resolve(designMdDir, filename);
      const markdown = fs.readFileSync(markdownPath, 'utf8').trim();
      if (!markdown) {
        throw new Error(`Empty DESIGN.md for slug "${slug}"`);
      }
      if (!MARKDOWN_SHAPE_RE.test(markdown)) {
        throw new Error(`Invalid markdown shape for slug "${slug}"`);
      }
      DESIGN_MD_BY_SLUG.set(slug, markdown);
      const name = toDisplayName(slug);
      const description = parseDescription(markdown);
      return {
        slug,
        name,
        category: 'Design System',
        description: description || `Design system for ${name}`,
        keywords: buildKeywords(slug),
        externalUrl: `https://getdesign.md/${slug}/design-md`,
      };
    });
};

export const DESIGN_SYSTEMS: DesignSystem[] = loadDesignSystems();

export const getDesignSystemBySlug = (
  slug: string,
): DesignSystem | null => {
  return DESIGN_SYSTEMS.find((entry) => entry.slug === slug) ?? null;
};

export const loadDesignSystemMarkdown = (slug: string): string | null => {
  return DESIGN_MD_BY_SLUG.get(slug) ?? null;
};
